const results = await Promise.allSettled([
  tools.exec_command({cmd:"find . -name AGENTS.md -o -name RoomSearchView.tsx -o -name '*SearchResultTile*' | head -100","workdir":"/app","yield_time_ms":10000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"git status --short && ls -la | head -50","workdir":"/app","yield_time_ms":10000,"max_output_tokens":3000})
]); for (const r of results) text(r.status==="fulfilled"?r.value.output:String(r.reason));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"sed -n '1,300p' src/components/structures/RoomSearchView.tsx","workdir":"/app","yield_time_ms":10000,"max_output_tokens":10000}),
  tools.exec_command({cmd:"sed -n '1,340p' src/components/views/rooms/SearchResultTile.tsx","workdir":"/app","yield_time_ms":10000,"max_output_tokens":10000}),
  tools.exec_command({cmd:"find test -iname '*RoomSearch*' -o -iname '*SearchResult*'; cat package.json | head -100","workdir":"/app","yield_time_ms":10000,"max_output_tokens":3500})
]); for (let i=0;i<results.length;i++) text(`--- ${i} ---\n${results[i].status==="fulfilled"?results[i].value.output:String(results[i].reason)}`);

