import { searchPagination } from "../../../src/Searching";

jest.mock("../../../src/Searching", () => ({
    searchPagination: jest.fn(),
}));

describe("<RoomSearchView/>", () => {
    const eventMapper = (obj: Partial<IEvent>) => new MatrixEvent(obj);
    const resizeNotifier = new ResizeNotifier();
    let client: MatrixClient;
    let room: Room;
    let permalinkCreator: RoomPermalinkCreator;
    const messageEvent = (eventId: string, body: string, ts: number): IEvent => ({
        room_id: room.roomId,
        event_id: eventId,
        sender: client.getUserId(),
        origin_server_ts: ts,
        content: { body, msgtype: "m.text" },
        type: EventType.RoomMessage,
    });
    const searchResult = (result: IEvent, eventsBefore: IEvent[], eventsAfter: IEvent[]): SearchResult =>
        SearchResult.fromJson(
            {
                rank: 1,
                result,
                context: {
                    profile_info: {},
                    events_before: eventsBefore,
                    events_after: eventsAfter,
                },
            },
            eventMapper,
        );

    beforeEach(async () => {
        stubClient();
        client = MatrixClientPeg.get();
        client.supportsExperimentalThreads = jest.fn().mockReturnValue(true);
        room = new Room("!room:server", client, client.getUserId());
        mocked(client.getRoom).mockReturnValue(room);
        permalinkCreator = new RoomPermalinkCreator(room, room.roomId);

        jest.spyOn(Element.prototype, "clientHeight", "get").mockReturnValue(100);
    });

    afterEach(async () => {
        jest.restoreAllMocks();
    });

    it("should show a spinner before the promise resolves", async () => {
        const deferred = defer<ISearchResults>();

        render(
            <RoomSearchView
                term="search term"
                scope={SearchScope.All}
                promise={deferred.promise}
                resizeNotifier={resizeNotifier}
                permalinkCreator={permalinkCreator}
                className="someClass"
                onUpdate={jest.fn()}
            />,
        );

        await screen.findByTestId("messagePanelSearchSpinner");
    });

    it("should render results when the promise resolves", async () => {
        render(
            <MatrixClientContext.Provider value={client}>
                <RoomSearchView
                    term="search term"
                    scope={SearchScope.All}
                    promise={Promise.resolve<ISearchResults>({
                        results: [
                            SearchResult.fromJson(
                                {
                                    rank: 1,
                                    result: {
                                        room_id: room.roomId,
                                        event_id: "$2",
                                        sender: client.getUserId(),
                                        origin_server_ts: 1,
                                        content: { body: "Foo Test Bar", msgtype: "m.text" },
                                        type: EventType.RoomMessage,
                                    },
                                    context: {
                                        profile_info: {},
                                        events_before: [
                                            {
                                                room_id: room.roomId,
                                                event_id: "$1",
                                                sender: client.getUserId(),
                                                origin_server_ts: 1,
                                                content: { body: "Before", msgtype: "m.text" },
                                                type: EventType.RoomMessage,
                                            },
                                        ],
                                        events_after: [
                                            {
                                                room_id: room.roomId,
                                                event_id: "$3",
                                                sender: client.getUserId(),
                                                origin_server_ts: 1,
                                                content: { body: "After", msgtype: "m.text" },
                                                type: EventType.RoomMessage,
                                            },
                                        ],
                                    },
                                },
                                eventMapper,
                            ),
                        ],
                        highlights: [],
                        count: 1,
                    })}
                    resizeNotifier={resizeNotifier}
                    permalinkCreator={permalinkCreator}
                    className="someClass"
                    onUpdate={jest.fn()}
                />
            </MatrixClientContext.Provider>,
        );

        await screen.findByText("Before");
        await screen.findByText("Foo Test Bar");
        await screen.findByText("After");
    });

    it("merges a chain of overlapping results and highlights each direct match", async () => {
        const before = messageEvent("$before", "search term before context", 1);
        const first = messageEvent("$first", "search term first", 2);
        const firstPivot = messageEvent("$first-pivot", "first pivot", 3);
        const secondContext = messageEvent("$second-context", "search term second context", 4);
        const second = messageEvent("$second", "search term second", 5);
        const secondPivot = messageEvent("$second-pivot", "second pivot", 6);
        const thirdContext = messageEvent("$third-context", "search term third context", 7);
        const third = messageEvent("$third", "search term third", 8);
        const after = messageEvent("$after", "after chain", 9);
        const separate = messageEvent("$separate", "search term separate", 10);

        // Search responses are newest first; RoomSearchView renders them in chronological order.
        const results = [
            searchResult(separate, [], []),
            searchResult(third, [secondPivot, thirdContext], [after]),
            searchResult(second, [firstPivot, secondContext], [secondPivot]),
            searchResult(first, [before], [firstPivot]),
        ];
        const { container } = render(
            <MatrixClientContext.Provider value={client}>
                <RoomSearchView
                    term="search term"
                    scope={SearchScope.Room}
                    promise={Promise.resolve<ISearchResults>({ results, highlights: [], count: results.length })}
                    resizeNotifier={resizeNotifier}
                    permalinkCreator={permalinkCreator}
                    className="someClass"
                    onUpdate={jest.fn()}
                />
            </MatrixClientContext.Provider>,
        );

        await screen.findByText("after chain");

        const resultTiles = container.querySelectorAll<HTMLElement>("li[data-scroll-tokens]:not(.mx_EventTile)");
        expect(resultTiles).toHaveLength(2);
        expect(
            Array.from(resultTiles[0].querySelectorAll<HTMLElement>(".mx_EventTile"), (tile) => tile.dataset.eventId),
        ).toEqual([
            "$before",
            "$first",
            "$first-pivot",
            "$second-context",
            "$second",
            "$second-pivot",
            "$third-context",
            "$third",
            "$after",
        ]);
        expect(
            Array.from(resultTiles[1].querySelectorAll<HTMLElement>(".mx_EventTile"), (tile) => tile.dataset.eventId),
        ).toEqual(["$separate"]);

        const eventTile = (eventId: string): HTMLElement | null =>
            container.querySelector<HTMLElement>(`.mx_EventTile[data-event-id="${eventId}"]`);
        for (const eventId of ["$first", "$second", "$third", "$separate"]) {
            const highlight = eventTile(eventId)?.querySelector(".mx_EventTile_searchHighlight");
            expect(highlight).toBeTruthy();
            expect(highlight?.closest("a")?.getAttribute("href")).toBe(`#/room/${room.roomId}/${eventId}`);
        }
        for (const eventId of ["$before", "$second-context", "$third-context"]) {
            expect(eventTile(eventId)?.querySelector(".mx_EventTile_searchHighlight")).toBeNull();
        }
    });

    it("merges results whose shared context event is a call event", async () => {
        const first = messageEvent("$first-message", "search term first", 1);
        const callPivot: IEvent = {
            room_id: room.roomId,
            event_id: "$call-pivot",
            sender: client.getUserId(),
            origin_server_ts: 2,
            content: { call_id: "call.1" },
            type: EventType.CallInvite,
        };
        const second = messageEvent("$second-message", "search term second", 3);
        const after = messageEvent("$after-call", "after call", 4);
        const results = [searchResult(second, [callPivot], [after]), searchResult(first, [], [callPivot])];

        const { container } = render(
            <MatrixClientContext.Provider value={client}>
                <RoomSearchView
                    term="search term"
                    scope={SearchScope.Room}
                    promise={Promise.resolve<ISearchResults>({ results, highlights: [], count: results.length })}
                    resizeNotifier={resizeNotifier}
                    permalinkCreator={permalinkCreator}
                    className="someClass"
                    onUpdate={jest.fn()}
                />
            </MatrixClientContext.Provider>,
        );

        await screen.findByText("after call");

        const resultTiles = container.querySelectorAll<HTMLElement>("li[data-scroll-tokens]:not(.mx_EventTile)");
        expect(resultTiles).toHaveLength(1);
        expect(
            Array.from(resultTiles[0].querySelectorAll<HTMLElement>(".mx_EventTile"), (tile) => tile.dataset.eventId),
        ).toEqual(["$first-message", "$call-pivot", "$second-message", "$after-call"]);
    });

    it("keeps the pivot as a match when it is the next result's direct match", async () => {
        const first = messageEvent("$first-match", "search term first", 1);
        const pivot = messageEvent("$pivot-match", "search term pivot", 2);
        const after = messageEvent("$after-pivot", "after pivot", 3);
        const after = messageEvent("$after-pivot", "after pivot", 3);
        const results = [searchResult(pivot, [], [after]), searchResult(first, [], [pivot])];

        const { container } = render(
            <MatrixClientContext.Provider value={client}>
                <RoomSearchView
                    term="search term"
                    scope={SearchScope.Room}
                    promise={Promise.resolve<ISearchResults>({ results, highlights: [], count: results.length })}
                    resizeNotifier={resizeNotifier}
                    permalinkCreator={permalinkCreator}
                    className="someClass"
                    onUpdate={jest.fn()}
                />
            </MatrixClientContext.Provider>,
        );

        await screen.findByText("after pivot");

        const resultTiles = container.querySelectorAll<HTMLElement>("li[data-scroll-tokens]:not(.mx_EventTile)");
        expect(resultTiles).toHaveLength(1);
        expect(
            Array.from(resultTiles[0].querySelectorAll<HTMLElement>(".mx_EventTile"), (tile) => tile.dataset.eventId),
        ).toEqual(["$first-match", "$pivot-match", "$after-pivot"]);
        const pivotHighlight = container.querySelector<HTMLElement>(
            '.mx_EventTile[data-event-id="$pivot-match"] .mx_EventTile_searchHighlight',
        );
        expect(pivotHighlight).toBeTruthy();
        expect(pivotHighlight?.closest("a")?.getAttribute("href")).toBe(`#/room/${room.roomId}/$pivot-match`);
    });

    it("should highlight words correctly", async () => {
        render(
            <MatrixClientContext.Provider value={client}>
                <RoomSearchView
                    term="search term"
                    scope={SearchScope.Room}
                    promise={Promise.resolve<ISearchResults>({
                        results: [
                            SearchResult.fromJson(
                                {
                                    rank: 1,
                                    result: {
                                        room_id: room.roomId,
                                        event_id: "$2",
                                        sender: client.getUserId(),
                                        origin_server_ts: 1,
                                        content: { body: "Foo Test Bar", msgtype: "m.text" },
                                        type: EventType.RoomMessage,
                                    },
                                    context: {
                                        profile_info: {},
                                        events_before: [],
                                        events_after: [],
                                    },
                                },
                                eventMapper,
                            ),
                        ],
                        highlights: ["test"],
                        count: 1,
                    })}
                    resizeNotifier={resizeNotifier}
